import React from 'react';
import { createRoot } from 'react-dom/client'; // Importiere createRoot
import { BrowserRouter as Router } from 'react-router-dom';
import App from './App';
import './index.css';

// Greife auf das DOM-Element zu, in das React gerendert wird
const container = document.getElementById('root');
const root = createRoot(container); // Erstelle ein createRoot

// Verwende createRoot, um die App zu rendern
root.render(
  <Router>
    <App />
  </Router>
);
